import{_ as i,a0 as a,w as d,s as c,ao as l,I as p,x as o,a1 as t,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"基础的Docker容器网络命令 | LCTT x X-CMD","titleTemplate":false,"description":"基础的Docker容器网络命令 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"基础的Docker容器网络命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"基础的Docker容器网络命令 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150515 Basic Networking Commands with Docker Containers","title":"基础的Docker容器网络命令","tag":"201506","desc":""},"relativePath":"201506/20150515 Basic Networking Commands with Docker Containers.md","filePath":"[post].md"}'),s={name:"201506/20150515 Basic Networking Commands with Docker Containers.md"};function k(m,e,g,h,u,b){const r=a("Link");return d(),c("div",null,[e[13]||(e[13]=l(`<h1 id="基础的docker容器网络命令" tabindex="-1">基础的Docker容器网络命令 <a class="header-anchor" href="#基础的docker容器网络命令" aria-label="Permalink to “基础的Docker容器网络命令”">​</a></h1><p>各位好，今天我们将学习一些Docker容器的基础命令。Docker 是一个开源项目，提供了一个可以打包、装载和运行任何应用的轻量级容器的开放平台。它没有语言支持、框架和打包系统的限制，从小型的家用电脑到高端服务器，在何时何地都可以运行。它可以使部署和扩展web应用程序、数据库和后端服务像搭积木一样容易，而不依赖特定技术栈或提供商。Docker适用于网络环境，它正应用于数据中心、ISP和越来越多的网络服务。</p><p>因此，这里有一些你在管理Docker容器的时候会用到的一些命令。</p><h3 id="_1-找到docker接口" tabindex="-1">1. 找到Docker接口 <a class="header-anchor" href="#_1-找到docker接口" aria-label="Permalink to “1. 找到Docker接口”">​</a></h3><p>Docker默认会创建一个名为docker0的网桥接口作为连接外部世界的基础。运行中的docker容器直接连接到网桥接口docker0。默认上，docker会分配172.17.42.1/16给docker0，它是所有运行中的容器ip地址的子网。找到Docker接口的ip地址非常简单。要找出docker0网桥接口和连接到网桥上的docker容器，我们可以在安装了docker的终端或者shell中运行ip命令。</p><pre><code># ip a
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-interface.png" alt="Docker Interface"></p><h3 id="_2-得到docker容器的ip地址" tabindex="-1">2. 得到Docker容器的ip地址 <a class="header-anchor" href="#_2-得到docker容器的ip地址" aria-label="Permalink to “2. 得到Docker容器的ip地址”">​</a></h3><p>如我们上面读到的，docker在宿主机中创建了一个叫docker0的网桥接口。在我们创建一个新的docker容器时，它自动被默认分配了一个在该子网范围内的ip地址。因此，要检测运行中的Docker容器的ip地址，我们需要进入一个正在运行的容器并用下面的命令检查ip地址。首先，我们运行一个新的容器并进入其中。如果你已经有一个正在运行的容器，你可以跳过这个步骤。</p><pre><code># docker run -it ubuntu
</code></pre><p>现在，我们可以运行ip a来得到容器的ip地址了。</p><pre><code># ip a
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-container-ip.png" alt="Docker Container IP"></p><h3 id="_3-映射暴露的端口" tabindex="-1">3. 映射暴露的端口 <a class="header-anchor" href="#_3-映射暴露的端口" aria-label="Permalink to “3. 映射暴露的端口”">​</a></h3><p>要映射配置在Dockerfile的暴露端口到宿主机的高位端口，我们只需用下面带上-P标志的命令。这会打开docker容器的随机端口并映射到Dockerfile中定义的端口。下面是使用-P来打开/暴露定义的端口的例子。</p><pre><code># docker run -itd -P httpd
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/mapping-expose-port.png" alt="Mapping Expose Port"></p><p>上面的命令会映射容器的端口到 httpd 容器的 Dockerfile 中定义的80端口上。我们用下面的命令来查看正在运行的容器暴露的端口。</p><pre><code># docker ps
</code></pre><p>并且可以用下面的curl命令来检查。</p><pre><code># curl http://localhost:49153
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/curl-exposed-port-e1431034586219.png" alt="Curl Exposed Port"></p><h3 id="_4-映射到特定的端口上" tabindex="-1">4. 映射到特定的端口上 <a class="header-anchor" href="#_4-映射到特定的端口上" aria-label="Permalink to “4. 映射到特定的端口上”">​</a></h3><p>我们也可以映射暴露端口或者docker容器端口到我们指定的端口上。要实现这个，我们用-p标志来定义我们所需的端口。这里是我们的一个例子。</p><pre><code># docker run -itd -p 8080:80 httpd
</code></pre><p>上面的命令会映射（宿主机的）8080端口到（容器的）80上。我们可以运行curl来检查这点。</p><pre><code># curl http://localhost:8080
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/mapping-specific-port.png" alt="Mapping Specific Port"></p><h3 id="_5-创建自己的网桥" tabindex="-1">5. 创建自己的网桥 <a class="header-anchor" href="#_5-创建自己的网桥" aria-label="Permalink to “5. 创建自己的网桥”">​</a></h3><p>要给容器创建一个自定义的IP地址，在本篇中我们会创建一个名为br0的新网桥。要分配需要的ip地址，我们需要在运行docker的宿主机中运行下面的命令。</p><pre><code># stop docker.io
# ip link add br0 type bridge
# ip addr add 172.30.1.1/20 dev br0
# ip link set br0 up
# docker -d -b br0
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/creating-bridge-interface.png" alt="Creating Bridge Interface"></p><p>创建完docker网桥之后，我们要让docker的守护进程知道它。</p><pre><code># echo &#39;DOCKER_OPTS=&quot;-b=br0&quot;&#39; &gt;&gt; /etc/default/docker
# service docker.io start
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/adding-interface-to-docker.png" alt="Adding Interface to Docker"></p><p>到这里，桥接后的接口将会分配给容器在桥接子网内的新ip地址。</p><h3 id="_6-链接到另外一个容器上" tabindex="-1">6. 链接到另外一个容器上 <a class="header-anchor" href="#_6-链接到另外一个容器上" aria-label="Permalink to “6. 链接到另外一个容器上”">​</a></h3><p>我们可以用Docker将一个容器连接到另外一个上。我们可以在不同的容器上运行不同的程序，并且相互连接或链接。链接允许容器间相互连接并从一个容器上安全地传输信息给另一个容器。要做到这个，我们可以使用--link标志。首先，我们使用--name标志来标示training/postgres镜像。</p><pre><code># docker run -d --name db training/postgres
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/running-db-container.png" alt="Running db Container"></p><p>完成之后，我们将容器db与training/webapp链接来形成新的叫web的容器。</p><pre><code># docker run -d -P --name web --link db:db training/webapp python app.py
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/linking-two-containers.png" alt="linking two containers"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>Docker网络很神奇也好玩，我们可以对docker容器做很多事情。我们可以把玩这些简单而基础的docker网络命令。docker的网络是非常先进的，我们可以用它做很多事情。</p><p>如果你有任何的问题、建议、反馈请在下面的评论栏写下来以便于我们我们可以提升或者更新文章的内容。谢谢！ 玩得开心！😃</p><hr>`,47)),p("p",null,[e[1]||(e[1]=o("via: ",-1)),t(r,{href:"http://linoxide.com/linux-how-to/networking-commands-docker-containers/"},{default:n(()=>[...e[0]||(e[0]=[o("http://linoxide.com/linux-how-to/networking-commands-docker-containers/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=o("作者：",-1)),t(r,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...e[2]||(e[2]=[o("Arun Pyasi",-1)])]),_:1}),e[6]||(e[6]=o(" 译者：",-1)),t(r,{href:"https://github.com/geekpi"},{default:n(()=>[...e[3]||(e[3]=[o("geekpi",-1)])]),_:1}),e[7]||(e[7]=o(" 校对：",-1)),t(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=o("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原创翻译，",-1)),t(r,{href:"https://linux.cn/"},{default:n(()=>[...e[9]||(e[9]=[o("Linux中国",-1)])]),_:1}),e[12]||(e[12]=o(" 荣誉推出",-1))])])}const w=i(s,[["render",k]]);export{D as __pageData,w as default};
